#include <stdio.h>
#include <stddef.h>

/* Contract: p must point at a live int (NULL is rejected). */
void add_bonus(int *p, int bonus) {
    if (p == NULL) return;
    *p += bonus;                 /* writes the caller's int. */
}

int *broken(void) {
    int total = 42;
    return &total;               /* DANGLING: total dies on return. */
}

int main(void) {
    int score = 7;
    int *p = &score;             /* p holds score's address. */
    add_bonus(p, 3);             /* score is now 10. */
    printf("%d %d\n", score, *p);

    int *q = NULL;               /* points at nothing: don't dereference. */
    int *r;                      /* uninitialised: invalid. */
    (void)q; (void)r;
    return 0;
}
```

| Pointer | Dereference? |
|---|---|
| `&score` while score lives. | yes. |
| `NULL`. | no (check first). |
| uninitialised. | no. |
| address of a local after its function returns. | no: dangling. |

